const modalOverlay = document.getElementById('projectModal');
const modalBody = document.querySelector('.project-modal-body');
const modalCloseBtn = document.querySelector('.project-modal-close');

function openProjectModal(title) {
  const data = projectDetails[title];
  if (!data || !modalOverlay || !modalBody) return;
  
  const currentLang = document.documentElement.lang || 'en';
  const t = modalTranslations[currentLang] || modalTranslations.en;
  
  const typeText = data.type[currentLang] || data.type.en;
  const resText = data.responsibilities[currentLang] || data.responsibilities.en;
  const lesText = data.lessons[currentLang] || data.lessons.en;
  const techText = data.tech ? (data.tech[currentLang] || data.tech.en) : '';
  
  // Notice for private projects
  const isPrivate = typeText.toLowerCase().includes('private') || typeText.toLowerCase().includes('cá nhân') || typeText.toLowerCase().includes('nội bộ') || typeText.toLowerCase().includes('корпоративный') || typeText.toLowerCase().includes('私有');
  const privateNotice = isPrivate ? `
    <div class="pm-notice">
      <i class="fa-solid fa-lock"></i>
      <span>${t.privateNote || modalTranslations.en.privateNote}</span>
    </div>
  ` : '';
  
  let techSection = '';
  if (techText) {
    const techItems = techText.split('. ').filter(t => t.trim()).map(t => {
      let str = t;
      if (str.endsWith('.')) str = str.slice(0, -1);
      const parts = str.split(': ');
      if (parts.length > 1) {
        return `<li><strong>${parts[0]}:</strong> ${parts.slice(1).join(': ')}</li>`;
      }
      return `<li>${str}</li>`;
    }).join('');
    
    techSection = `
      <div class="pm-section">
        <h4><i class="fa-solid fa-code"></i> ${t.tech || modalTranslations.en.tech}</h4>
        <ul style="margin:0; padding-left:20px; color:var(--muted); font-size:15px; line-height:1.7;">
          ${techItems}
        </ul>
      </div>
    `;
  }
  
  const teamSizeLabel = t.teamSize || (currentLang === 'vi' ? 'Quy mô nhóm' : 'Team Size');
  const companyLabel = t.company || (currentLang === 'vi' ? 'Công ty / Khách hàng' : 'Company / Customer');
  const imagesLabel = t.images || (currentLang === 'vi' ? 'Hình ảnh dự án' : 'Project Images');

  let imagesSection = '';
  if (data.images && data.images.length > 0) {
    currentLightboxImages = data.images || [];
    const imgs = data.images.map((img, idx) => `<img src="${img}" alt="Project Image" style="width:100%; border-radius:8px; border:1px solid var(--line); margin-bottom:8px; cursor:zoom-in; transition:opacity 0.2s;" onclick="openLightbox(${idx})" onmouseover="this.style.opacity=0.8" onmouseout="this.style.opacity=1">`).join('');
    imagesSection = `
      <div class="pm-section">
        <h4><i class="fa-solid fa-images"></i> ${imagesLabel}</h4>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 15px; margin-top: 15px;">
          ${imgs}
        </div>
      </div>
    `;
  }

  let resSection = '';
  if (resText) {
    const resItems = (Array.isArray(resText) ? resText : resText.split('. ').filter(t => t.trim())).map(t => {
      let str = t;
      if (str.endsWith('.')) str = str.slice(0, -1);
      return `<li style="margin-bottom: 6px;">${str}</li>`;
    }).join('');
    resSection = `
      <div class="pm-section">
        <h4><i class="fa-solid fa-layer-group"></i> ${t.responsibilities}</h4>
        <ul style="margin:0; padding-left:20px; color:var(--muted); font-size:15px; line-height:1.7;">
          ${resItems}
        </ul>
      </div>
    `;
  }

  let lesSection = '';
  if (lesText) {
    const lesItems = (Array.isArray(lesText) ? lesText : lesText.split('. ').filter(t => t.trim())).map(t => {
      let str = t;
      if (str.endsWith('.')) str = str.slice(0, -1);
      return `<li style="margin-bottom: 6px;">${str}</li>`;
    }).join('');
    lesSection = `
      <div class="pm-section">
        <h4><i class="fa-solid fa-lightbulb"></i> ${t.lessons}</h4>
        <ul style="margin:0; padding-left:20px; color:var(--muted); font-size:15px; line-height:1.7;">
          ${lesItems}
        </ul>
      </div>
    `;
  }

  modalBody.innerHTML = `
    <h2 class="pm-title" style="margin-bottom: 24px;">${title}</h2>
    
    ${privateNotice}

    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 24px; margin-bottom: 24px;">
      <div class="pm-section" style="margin-bottom: 0;">
        <h4><i class="fa-solid fa-user-gear"></i> ${t.role}</h4>
        <p>${data.role}</p>
      </div>
      <div class="pm-section" style="margin-bottom: 0;">
        <h4><i class="fa-solid fa-building-lock"></i> ${t.type}</h4>
        <p>${typeText}</p>
      </div>
      <div class="pm-section" style="margin-bottom: 0;">
        <h4><i class="fa-solid fa-users"></i> ${teamSizeLabel}</h4>
        <p>${data.teamSize || 'N/A'}</p>
      </div>
      <div class="pm-section" style="margin-bottom: 0;">
        <h4><i class="fa-solid fa-building"></i> ${companyLabel}</h4>
        <p>${data.company || 'N/A'}</p>
      </div>
    </div>
    
    ${techSection}
    
    ${resSection}
    
    ${lesSection}
    
    ${(function() {
      let privateLinkTexts = {
        vi: "Private Policy (Không thể truy cập)",
        en: "Private Policy (Inaccessible)",
        ja: "プライベートポリシー (アクセス不可)",
        zh: "隐私政策 (不可访问)",
        ru: "Частная политика (Недоступно)"
      };
      let pText = privateLinkTexts[currentLang] || privateLinkTexts.vi;
      if (data.link && data.link.startsWith('http')) {
          return `<a href="${data.link}" target="_blank" class="pm-link"><i class="fa-solid fa-globe"></i> ${data.link}</a>`;
      } else {
          return `<a href="#" class="pm-link" style="cursor: not-allowed; opacity: 0.7; pointer-events: none;"><i class="fa-solid fa-lock"></i> ${pText}</a>`;
      }
    })()}
    
    ${imagesSection}
  `;
  
  modalOverlay.classList.add('active');
  document.body.style.overflow = 'hidden';
  modalOverlay.setAttribute('data-current-project', title);
}

document.querySelectorAll('.project').forEach(card => {
  card.addEventListener('click', () => {
    const titleEl = card.querySelector('h3');
    if(!titleEl) return;
    openProjectModal(titleEl.innerText.trim());
  });
});

// Update modal content on language switch if it's currently open
langSelects.forEach(select => {
  select.addEventListener('change', (e) => {
    if (modalOverlay && modalOverlay.classList.contains('active')) {
      const activeProject = modalOverlay.getAttribute('data-current-project');
      if (activeProject) {
        // slight delay to allow language state to update
        setTimeout(() => { openProjectModal(activeProject); }, 50);
      }
    }
  });
});

function closeModal() {
  if(modalOverlay) {
    modalOverlay.classList.remove('active');
    document.body.style.overflow = '';
  }
}

if(modalCloseBtn) modalCloseBtn.addEventListener('click', closeModal);
if(modalOverlay) modalOverlay.addEventListener('click', (e) => {
  if(e.target === modalOverlay || e.target.classList.contains('project-modal-backdrop')) {
    closeModal();
  }
});
document.addEventListener('keydown', (e) => {
  if(e.key === 'Escape' && modalOverlay && modalOverlay.classList.contains('active')) {
    closeModal();
  }
});


