let currentLightboxImages = [];
let currentLightboxIndex = 0;

function openLightbox(index) {
  if (!currentLightboxImages || currentLightboxImages.length === 0) return;
  currentLightboxIndex = index;
  const lb = document.getElementById('lightbox');
  lb.classList.add('active');
  renderThumbnails();
  jumpLightbox(index);
}

function closeLightbox() {
  document.getElementById('lightbox').classList.remove('active');
}

function renderThumbnails() {
  const container = document.getElementById('lightbox-thumbnails');
  container.innerHTML = currentLightboxImages.map((img, idx) => 
    `<img src="${img}" class="${idx === currentLightboxIndex ? 'active' : ''}" onclick="jumpLightbox(${idx})">`
  ).join('');
}

function jumpLightbox(index) {
  currentLightboxIndex = index;
  updateLightboxImage();
}

function prevLightbox() {
  if (!currentLightboxImages || currentLightboxImages.length === 0) return;
  currentLightboxIndex = (currentLightboxIndex - 1 + currentLightboxImages.length) % currentLightboxImages.length;
  updateLightboxImage();
}

function nextLightbox() {
  if (!currentLightboxImages || currentLightboxImages.length === 0) return;
  currentLightboxIndex = (currentLightboxIndex + 1) % currentLightboxImages.length;
  updateLightboxImage();
}

function updateLightboxImage() {
  const img = document.getElementById('lightbox-img');
  const counter = document.getElementById('lightbox-counter');
  const thumbs = document.getElementById('lightbox-thumbnails').querySelectorAll('img');
  
  thumbs.forEach((t, idx) => {
    if (idx === currentLightboxIndex) {
      t.classList.add('active');
      t.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
    } else {
      t.classList.remove('active');
    }
  });
  
  img.style.opacity = '0.4';
  setTimeout(() => {
    img.src = currentLightboxImages[currentLightboxIndex];
    counter.innerText = (currentLightboxIndex + 1) + " / " + currentLightboxImages.length;
    img.style.opacity = '1';
  }, 150);
}

// Add keyboard navigation
document.addEventListener('keydown', function(e) {
  const lb = document.getElementById('lightbox');
  if (lb && lb.classList.contains('active')) {
    if (e.key === 'Escape') closeLightbox();
    else if (e.key === 'ArrowLeft') prevLightbox();
    else if (e.key === 'ArrowRight') nextLightbox();
  }
});

